  href,
  variant = 'primary',
  size = 'md',
  type = 'button',
  attrs: extra = {},
}) {
  const v = VARIANTS.has(variant) ? variant : 'primary';
  const cls = cx('kit-btn', `kit-btn--${v}`, size === 'sm' && 'kit-btn--sm');
